<script setup lang="ts">
import {ref,watch} from 'vue';import Modal from './Modal.vue';import AccountConnect from './AccountConnect.vue';import Icon from './Icon.vue';import {request,waitJob,errorText} from '../api';const emit=defineEmits<{close:[]}>();const step=ref(Math.max(1,Math.min(5,Number(localStorage.getItem('offerpilot.wizard_step'))||1))),busy=ref(false),error=ref(''),notice=ref('');
watch(step,v=>localStorage.setItem('offerpilot.wizard_step',String(v)));function receipt(seen:boolean){localStorage.setItem('offerpilot.notice_receipt',seen?'seen':'not_seen');notice.value=seen?'已记录本次测试反馈。':'已记录：未看到系统通知。仍可使用应用内提醒，请检查 Windows 通知设置。';}
async function finish(){busy.value=true;try{const s=await request('/settings');await request('/settings','PATCH',{expected_version:s.version,changes:{onboarding_completed:true}});localStorage.removeItem('offerpilot.wizard_step');emit('close');}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function test(){busy.value=true;try{const j=await request('/notifications/test','POST',{channel:'windows'});if(j.job_id)await waitJob(j.job_id);notice.value='测试已提交。请检查 Windows 通知；没有看到也可以继续使用应用内提醒。';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function sync(){busy.value=true;try{const accounts=await request('/accounts');if(!accounts.length){notice.value='还没有连接邮箱，可以先导入 .eml 或添加手动待办。';return;}const j=await request('/sync/trigger','POST',{account_id:accounts[0].id});await waitJob(j.job_id??j.sync_run_id);notice.value='首次同步已完成，去查看你的待办和待确认邮件吧。';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function connectionResult(tested=false){notice.value=tested?'邮箱连接成功。':'邮箱已保存，但尚未连接成功。请检查授权码后重试。';}
</script>
<template><Modal title="欢迎来到 OfferPilot" @close="emit('close')"><div class="form-body onboarding"><div class="step-track"><span v-for="n in 5" :class="{active:n<=step}">{{n}}</span></div><template v-if="step===1"><div class="welcome-symbol"><Icon name="leaf" :size="48"/></div><h2>求职路上，多一份从容。</h2><p>把分散的招聘通知整理成清楚的行动，让你把心思留给准备。</p><ul class="promise-list"><li>邮件只读，数据默认保存在本机</li><li>不明确的时间，由你亲自确认</li><li>电脑运行时提醒；休眠或退出后暂停</li></ul></template><template v-if="step===2"><h2>连接你的邮箱</h2><p class="muted">也可以跳过，先体验手动待办或导入邮件。</p><AccountConnect @connected="connectionResult"/></template><template v-if="step===3"><h2>先从可靠的规则识别开始</h2><div class="choice-card"><span class="badge">默认开启</span><h3>本地规则解析</h3><p>识别招聘动作、提取明确时间，并保存来源依据。模糊内容进入待确认。</p></div><p class="field-help">默认不向 AI 发送邮件。需要辅助建议时，可在设置中填写模型服务并明确同意发送范围。</p></template><template v-if="step===4"><h2>确认提醒能够到达</h2><p>先发送一条无真实求职信息的测试通知。</p><button class="button" :disabled="busy" @click="test"><Icon name="bell" :size="18"/>发送测试通知</button><p class="field-help">系统勿扰设置可能隐藏横幅，应用内提醒记录会继续保留。</p><div class="button-row"><button class="button" @click="receipt(true)">我看到了通知</button><button class="button" @click="receipt(false)">没有看到，继续使用应用内提醒</button></div></template><template v-if="step===5"><h2>你的下一步，已经准备好了</h2><p>连接过邮箱后，可以开始首次同步。稍后也能在设置中随时手动同步。</p><button class="button" :disabled="busy" @click="sync">开始首次同步</button></template><p v-if="notice" class="success-box">{{notice}}</p><p v-if="error" class="error-box" role="alert">{{error}}</p></div><footer class="modal-actions"><button class="text-button" :disabled="busy" @click="finish">先体验待办</button><div class="spacer"/><button v-if="step>1" class="button" :disabled="busy" @click="step--;notice='';error=''">上一步</button><button class="button primary" :disabled="busy" @click="step<5?(step++,notice='',error=''):finish()">{{step===5?'进入我的空间':step===2?'继续 / 暂时跳过':'下一步'}}<Icon name="arrow" :size="17"/></button></footer></Modal></template>
